<?php
declare(strict_types=1);require_once '../config/config.php';require_once '../includes/church-book-functions.php';requireLogin();cb_require_permission('visitors.view');$conn->set_charset('utf8mb4');
$q=cb_clean($_GET['q']??'');$type=cb_clean($_GET['type']??'');$follow=cb_clean($_GET['follow']??'');$from=cb_clean($_GET['from']??'');$to=cb_clean($_GET['to']??'');$where=['1=1'];$types='';$params=[];
if($q!==''){$where[]="(full_name LIKE ? OR phone LIKE ? OR email LIKE ? OR service_attended LIKE ?)";$like="%{$q}%";for($i=0;$i<4;$i++){$params[]=$like;$types.='s';}}if(in_array($type,['First Time','Returning'],true)){$where[]='visitor_type=?';$params[]=$type;$types.='s';}if(in_array($follow,['Not Required','Pending','Contacted','Completed'],true)){$where[]='follow_up_status=?';$params[]=$follow;$types.='s';}if($from!==''&&cb_valid_date($from)){$where[]='visit_date>=?';$params[]=$from;$types.='s';}if($to!==''&&cb_valid_date($to)){$where[]='visit_date<=?';$params[]=$to;$types.='s';}
$rows=cb_fetch_all($conn,"SELECT * FROM church_visitors WHERE ".implode(' AND ',$where)." ORDER BY visit_date ASC,id ASC",$types,$params);$site=cb_site_setting($conn,'site_name','Church Management System');
?><!doctype html><html><head><meta charset="utf-8"><title>Church Visitors Book</title><style>body{font-family:Arial,sans-serif;color:#111;margin:24px}h1,h2,p{text-align:center;margin:4px}.meta{margin:15px 0;font-size:12px}table{width:100%;border-collapse:collapse;font-size:10px}th,td{border:1px solid #555;padding:6px;vertical-align:top}th{background:#eee}.actions{text-align:right;margin-bottom:15px}@media print{.actions{display:none}body{margin:8mm}}</style></head><body><div class="actions"><button onclick="window.print()">Print</button></div><h2><?= cb_h($site) ?></h2><h1>Church Visitors Book</h1><p>Printed <?= date('d M Y, H:i') ?></p><div class="meta">Records: <?= count($rows) ?></div><table><thead><tr><th>#</th><th>Date</th><th>Visitor</th><th>Contact / Address</th><th>Type</th><th>Service</th><th>Invited By</th><th>Follow-up</th><th>Notes / Prayer Request</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td><?= $i+1 ?></td><td><?= cb_h($r['visit_date']) ?></td><td><strong><?= cb_h($r['full_name']) ?></strong><br><?= cb_h($r['gender']) ?></td><td><?= cb_h($r['phone']) ?><br><?= cb_h($r['email']) ?><br><?= cb_h($r['address']) ?></td><td><?= cb_h($r['visitor_type']) ?></td><td><?= cb_h($r['service_attended']) ?></td><td><?= cb_h($r['invited_by']) ?></td><td><?= cb_h($r['follow_up_status']) ?><br><?= cb_h($r['assigned_to']) ?></td><td><?= cb_h($r['notes']) ?><br><?= cb_h($r['prayer_request']) ?></td></tr><?php endforeach;?></tbody></table></body></html>
